-- T018 — the idempotency key becomes the actor's (specs/002-identity/data-model.md §1
-- "idempotency_keys", §5 rule 26, §8; ERD §12, §15 rule 26; FR-106; contracts/kernel.md
-- "Idempotency"). Generated by `prisma migrate diff --from-config-datasource --to-schema
-- prisma/schema --script` against a database holding every migration before it. Nothing is
-- hand-written: the NOT NULL column and the three-column unique are what the schema says, and the
-- table holds no row that the column could leave without a value (the seed writes none; the
-- repository that writes the column lands in the same batch, B4, as the conflict review of
-- 2026-10-18 decided). Rule 16's `(scope, key)` unique is dropped: two actors who send one key each
-- get their own row, and the service refuses to key an anonymous mutation.

-- DropIndex
DROP INDEX "idempotency_keys_scope_key_key";

-- AlterTable
ALTER TABLE "idempotency_keys" ADD COLUMN     "actor_id" TEXT NOT NULL;

-- CreateIndex
CREATE UNIQUE INDEX "idempotency_keys_scope_actor_id_key_key" ON "idempotency_keys"("scope", "actor_id", "key");
